from pathlib import Path
p=Path('/mnt/data/current_brand_upgrade/app/[[...slug]]/Storefront.tsx')
s=p.read_text()

old='const API_VERSION=process.env.NEXT_PUBLIC_SHOPIFY_API_VERSION||"2026-07";\nconst LOGO_SRC="/images/buyhoreca-logo-header.png";'
new='const API_VERSION=process.env.NEXT_PUBLIC_SHOPIFY_API_VERSION||"2026-07";\nconst BRAND_METAOBJECT_TYPE=process.env.NEXT_PUBLIC_SHOPIFY_BRAND_METAOBJECT_TYPE||"brand";\nconst LOGO_SRC="/images/buyhoreca-logo-header.png";'
assert old in s
s=s.replace(old,new,1)

old='const ARTICLE=`query Article($blog:String!,$handle:String!){blog(handle:$blog){articleByHandle(handle:$handle){${ARTICLE_FIELDS}}}}`;'
new='const ARTICLE=`query Article($blog:String!,$handle:String!){blog(handle:$blog){articleByHandle(handle:$handle){${ARTICLE_FIELDS}}}}`;\nconst BRAND_METAOBJECTS=`query BrandMetaobjects($type:String!,$first:Int!,$after:String){metaobjects(type:$type,first:$first,after:$after){pageInfo{hasNextPage endCursor}nodes{id handle type fields{key value reference{... on MediaImage{image{url altText width height}}}}}}}`;'
assert old in s
s=s.replace(old,new,1)

old='type Blog={id:string;handle:string;title:string;articles:BlogArticle[]};'
new='type Blog={id:string;handle:string;title:string;articles:BlogArticle[]};\ntype BrandRecord={id:string;handle:string;name:string;vendor:string;logo?:ImageData|null;description?:string|null;featured:boolean;sortOrder:number};'
assert old in s
s=s.replace(old,new,1)

old='async function getArticle(blog:string,handle:string){const d:any=await shopifyFetch(ARTICLE,{blog,handle});return d.blog?.articleByHandle?normalizeArticle(d.blog.articleByHandle):null;}\n'
new='''async function getArticle(blog:string,handle:string){const d:any=await shopifyFetch(ARTICLE,{blog,handle});return d.blog?.articleByHandle?normalizeArticle(d.blog.articleByHandle):null;}\nfunction metaFieldValue(raw:any,key:string):string{const f=(raw?.fields||[]).find((x:any)=>x?.key===key);return typeof f?.value==="string"?f.value.trim():"";}\nfunction metaFieldImage(raw:any,key:string):ImageData|null{const f=(raw?.fields||[]).find((x:any)=>x?.key===key);return f?.reference?.image||null;}\nfunction normalizeBrandMetaobject(raw:any):BrandRecord|null{\n const name=metaFieldValue(raw,"name")||metaFieldValue(raw,"title")||raw?.handle||"";\n if(!name)return null;\n const vendor=metaFieldValue(raw,"vendor")||name;\n const sortRaw=Number(metaFieldValue(raw,"sort_order"));\n const featuredRaw=metaFieldValue(raw,"featured").toLowerCase();\n return {id:raw.id,handle:raw.handle,name,vendor,logo:metaFieldImage(raw,"logo"),description:metaFieldValue(raw,"description")||null,featured:featuredRaw==="true"||featuredRaw==="1"||featuredRaw==="yes",sortOrder:Number.isFinite(sortRaw)?sortRaw:999999};\n}\nasync function getBrandMetaobjects():Promise<BrandRecord[]>{\n let after:string|null=null; const out:BrandRecord[]=[];\n try{\n  do{\n   const d:any=await shopifyFetch(BRAND_METAOBJECTS,{type:BRAND_METAOBJECT_TYPE,first:250,after});\n   for(const raw of d?.metaobjects?.nodes||[]){const brand=normalizeBrandMetaobject(raw);if(brand)out.push(brand)}\n   after=d?.metaobjects?.pageInfo?.hasNextPage?d.metaobjects.pageInfo.endCursor:null;\n  }while(after);\n  return out;\n }catch{return []}\n}\n'''
assert old in s
s=s.replace(old,new,1)

start=s.index('function BrandShowcase({products}:{products:Product[]}){')
end=s.index('\nfunction CompanyProof', start)
replacement='''function BrandShowcase({products}:{products:Product[]}){\n const [managed,setManaged]=useState<BrandRecord[]>([]);\n useEffect(()=>{let live=true;getBrandMetaobjects().then(items=>{if(live)setManaged(items)});return()=>{live=false}},[]);\n const discovered=Array.from(new Set(products.map(p=>p.brand).filter((b):b is string=>Boolean(b)&&b!=="BuyHoreca"))).sort((a,b)=>a.localeCompare(b));\n const managedSorted=[...managed].sort((a,b)=>(a.featured===b.featured?a.sortOrder-b.sortOrder:Number(b.featured)-Number(a.featured))||a.name.localeCompare(b.name));\n const byVendor=new Map(managedSorted.map(b=>[b.vendor.toLowerCase(),b]));\n const fallbackNames=["Vollrath","iSi","Eros","Eco-Botanics","Ziora","Winco","Cambro","Carlisle","Mercer Culinary","San Jamar","Bunn","Knicer","Pujadas"];\n const vendorOnly=[...new Set([...fallbackNames,...discovered])].filter(name=>!byVendor.has(name.toLowerCase()));\n const entries:[BrandRecord,string][]=[...managedSorted.map(b=>[b,b.name] as [BrandRecord,string]),...vendorOnly.map(name=>[byVendor.get(name.toLowerCase())||({id:name,handle:slugify(name),name,vendor:name,logo:null,description:null,featured:false,sortOrder:999999} as BrandRecord),name] as [BrandRecord,string])];\n const deduped=Array.from(new Map(entries.map(([b,label])=>[(b.vendor||label).toLowerCase(),[b,label] as [BrandRecord,string]])).values()).slice(0,24);\n return <section className="mx-auto max-w-[1600px] px-4 py-8"><div className="rounded border border-slate-200 bg-white p-5 md:p-6"><div className="flex items-end justify-between gap-4"><div><div className="text-[10px] font-semibold uppercase tracking-[.16em] text-slate-500">Trusted manufacturers</div><h2 className="mt-1 text-[24px] font-bold">Popular brands</h2><p className="mt-1 max-w-2xl text-sm text-slate-500">Explore manufacturers represented by the live BuyHoreca catalogue.</p></div><Link href="/brands" className="shrink-0 text-sm font-medium text-[#008f68]">View all brands <ArrowRight size={14} className="inline"/></Link></div><div className="mt-5 grid grid-cols-2 gap-2.5 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-6 xl:grid-cols-8">{deduped.map(([brand,label])=>{const src=brand.logo?.url||brandLogoFor(label);return <Link key={`${brand.id}-${label}`} href={`/brands/${encodeURIComponent(brand.vendor||label)}`} className="bh-brand-tile group flex min-h-[94px] items-center justify-center rounded border border-slate-200 bg-slate-50 px-3 py-4 text-center transition hover:-translate-y-0.5 hover:border-[#008f68] hover:bg-white hover:shadow-sm"><div className="flex w-full items-center justify-center">{src?<img src={src} alt={`${label} logo`} className="max-h-16 w-auto max-w-[150px] object-contain transition duration-300 group-hover:scale-[1.03]" loading="lazy"/>:<span className="text-sm font-medium uppercase tracking-[.04em] text-slate-600 transition group-hover:text-[#008f68]">{label}</span>}</div></Link>})}</div></div></section>}\n'''
s=s[:start]+replacement+s[end:]

start=s.index('function BrandIndex({products}:{products:Product[]}){')
end=s.index('\nfunction BrandPage', start)
replacement='''function BrandIndex({products}:{products:Product[]}){\n const [managed,setManaged]=useState<BrandRecord[]>([]);\n useEffect(()=>{let live=true;getBrandMetaobjects().then(items=>{if(live)setManaged(items)});return()=>{live=false}},[]);\n const discovered=Array.from(new Set(products.map(p=>p.brand).filter((b):b is string=>Boolean(b))));\n const managedSorted=[...managed].sort((a,b)=>(a.featured===b.featured?a.sortOrder-b.sortOrder:Number(b.featured)-Number(a.featured))||a.name.localeCompare(b.name));\n const byVendor=new Map(managedSorted.map(b=>[b.vendor.toLowerCase(),b]));\n const names=Array.from(new Set([...managedSorted.map(b=>b.vendor),...discovered,"Vollrath","iSi","Eros","Eco-Botanics","Ziora"])).sort((a,b)=>a.localeCompare(b));\n return <main className="mx-auto max-w-[1600px] px-4 py-8">\n  <div className="flex flex-col gap-3 border-b border-slate-200 pb-6 md:flex-row md:items-end md:justify-between"><div><div className="text-xs font-semibold uppercase tracking-widest text-[#008f68]">Manufacturers</div><h1 className="mt-2 text-4xl font-bold">Shop by Brand</h1><p className="mt-3 max-w-3xl text-sm leading-6 text-slate-600">Browse the live BuyHoreca brand catalogue. Brand names follow Shopify vendor data; managed brand logos and merchandising can be maintained in Shopify.</p></div><div className="text-xs text-slate-500">{names.length.toLocaleString()} brands</div></div>\n  <div className="mt-7 grid grid-cols-2 gap-3 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-6">\n   {names.map(b=>{const meta=byVendor.get(b.toLowerCase());const src=meta?.logo?.url||brandLogoFor(b);return <Link key={b} href={`/brands/${encodeURIComponent(b)}`} className="bh-brand-tile group flex min-h-[118px] items-center justify-center border border-slate-200 bg-white p-5 text-center transition hover:-translate-y-0.5 hover:border-[#008f68] hover:shadow-sm">{src?<img src={src} alt={`${b} logo`} className="max-h-16 max-w-full object-contain transition duration-300 group-hover:scale-[1.03]" loading="lazy"/>:<span className="text-sm font-medium uppercase tracking-[.04em] text-slate-600 transition group-hover:text-[#008f68]">{b}</span>}</Link>})}\n  </div>\n </main>\n}\n'''
s=s[:start]+replacement+s[end:]

# BrandPage: show managed logo/description if available.
start=s.index('function BrandPage({name,onAdd,onQuick}:{name:string;onAdd:any;onQuick:any}){')
end=s.index('\nfunction BusinessIndex', start)
replacement='''function BrandPage({name,onAdd,onQuick}:{name:string;onAdd:any;onQuick:any}){\n const [items,setItems]=useState<Product[]>([]); const [meta,setMeta]=useState<BrandRecord|null>(null);\n useEffect(()=>{let live=true;Promise.all([getProducts(48,null,`vendor:"${name.replaceAll('"','')}"`,"BEST_SELLING",false),getBrandMetaobjects()]).then(([r,brands])=>{if(!live)return;setItems(r.products);setMeta(brands.find(b=>b.vendor.toLowerCase()===name.toLowerCase()||b.name.toLowerCase()===name.toLowerCase())||null)}).catch(()=>{if(live){setItems([]);setMeta(null)}});return()=>{live=false}},[name]);\n const logo=meta?.logo?.url||brandLogoFor(name);\n return <main className="mx-auto max-w-[1600px] px-4 py-8">\n  <div className="border-b border-slate-200 pb-6">\n   <div className="text-xs font-semibold uppercase tracking-widest text-[#008f68]">Brand</div>\n   <div className="mt-3 flex flex-wrap items-center gap-5">\n    {logo&&<div className="flex h-20 w-40 items-center justify-center border border-slate-200 bg-white p-3"><img src={logo} alt={`${name} logo`} className="max-h-14 max-w-full object-contain"/></div>}\n    <div><h1 className="text-4xl font-bold">{meta?.name||name}</h1><p className="mt-2 max-w-2xl text-sm text-slate-600">{meta?.description||"Products available from this manufacturer in the live BuyHoreca catalogue."}</p></div>\n   </div>\n  </div>\n  {!items.length?<div className="mt-8 rounded border border-dashed border-slate-300 bg-slate-50 p-12 text-center text-sm text-slate-500">No products are currently available for this brand in the live catalogue.</div>:<div className="bh-catalog-grid mt-7">{items.map(p=><ProductCard key={p.id} p={p} onAdd={onAdd} onQuick={onQuick}/>)}</div>}\n </main>\n}\n'''
s=s[:start]+replacement+s[end:]

# Remove remote GitHub fallback so runtime never depends on raw.githubusercontent for logos.
s=s.replace('const BRAND_LOGO_REMOTE="https://raw.githubusercontent.com/mohammedrazilrahees01-stack/Buyhoreca_ecommerce/main/public/images/brands/";\n','')
s=s.replace('const brandRemotePaths:Record<string,string>={\n  "winco":"Logo_Winco.jpg","cambro":"Logo_Cambro.avif","carlisle":"Logo_Carlisle.jpg","mercer culinary":"Logo_Mercer_Culinary.jpg","san jamar":"Logo_San_Jamer.jpg","bunn":"Bunn_Logo.avif","knicer":"Logo_Knicer.jpg","bisetti":"Logo_Bisetti.jpg","brewing edge":"Logo_Brewing_Edge.jpg","borgonova":"Logo_Borgonova.jpg","cooper atkins":"Logo_Cooper_Atkins.jpg","cutlerypro":"Logo_Cutlery_Pro.jpg","edhard":"Logo_Edhard.jpg","gi metal":"Logo_Gimetal.avif","kalando":"Logo_Kalando.avif","sonoco":"Logo_Sonoco.jpg","thermo hauser":"Logo_Thermo_Hauser.avif","tight vac":"Logo_Tight_Vac.jpg"\n};\n','')
# Remove brandLogoRemoteFor function and its onError fallback code
s=s.replace('function brandLogoRemoteFor(name:string):string|undefined{const file=brandRemotePaths[name.trim().toLowerCase()];return file?`${BRAND_LOGO_REMOTE}${file}`:undefined}\n','')
s=s.replace(' onError={(e)=>{if(e.currentTarget.dataset.fallback==="1"){e.currentTarget.style.display="none";return;}const remote=brandLogoRemoteFor(name);if(remote){e.currentTarget.dataset.fallback="1";e.currentTarget.src=remote;}}}','')
s=s.replace(' onError={(e)=>{if(e.currentTarget.dataset.fallback==="1"){e.currentTarget.style.display="none";return;}const remote=brandLogoRemoteFor(b);if(remote){e.currentTarget.dataset.fallback="1";e.currentTarget.src=remote;}}}','')

p.write_text(s)
print('patched', len(s))
